#!/usr/bin/env bash
# Generate three self-contained WASM bench mains (noop/float/ternary) for given T D REPS.
# Usage: gen_bench.sh <T> <D> <REPS>
set -euo pipefail
T="${1:-64}"; D="${2:-256}"; REPS="${3:-300}"
DIR="$(cd "$(dirname "$0")" && pwd)"

emit() {
  local mode="$1" kernel="$2"
  cat > "$DIR/bench_${mode}.almd" <<EOF
// GENERATED by gen_bench.sh — mode=${mode}, T=${T}, D=${D}, REPS=${REPS}. Self-contained (no args).
import float
import math
import self.dotrows
import self.ternarydot

effect fn main() -> Unit = {
  let t = ${T}
  let d = ${D}
  let reps = ${REPS}
  let rowsA = list.map(list.range(0, t), (i) =>
    list.map(list.range(0, d), (j) => math.sin(int.to_float(i) * 0.1 + int.to_float(j) * 0.017)))
  let rowsB = list.map(list.range(0, t), (i) =>
    list.map(list.range(0, d), (j) => math.cos(int.to_float(i) * 0.07 + int.to_float(j) * 0.013)))
  let b = matrix.from_lists(rowsB)
  var acc = 0.0
  var r = 0
  while r < reps {
    let f = int.to_float(r) * 0.0000001
    let ar = matrix.from_lists(list.map(rowsA, (row) => list.map(row, (v) => v + f)))
    let cell = ${kernel}
    acc = acc + cell
    r = r + 1
  }
  println("${mode} t=" + int.to_string(t) + " d=" + int.to_string(d) + " reps=" + int.to_string(reps) + " checksum=" + int.to_string(float.to_int(acc * 1000000.0)))
}
EOF
}

emit noop    "matrix.get(ar, 0, 0)"
emit float   "matrix.get(dotrows.dot_rows(ar, b), 0, 0)"
emit ternary "matrix.get(ternarydot.ternary_dot_rows(ar, b), 0, 0)"
echo "generated bench_{noop,float,ternary}.almd  (T=$T D=$D REPS=$REPS)"
